/* @autogenerated */
package net.civeira.phylax.feature.observe.ingest;

import jakarta.annotation.Priority;
import jakarta.ws.rs.Priorities;
import jakarta.ws.rs.container.ContainerRequestContext;
import jakarta.ws.rs.container.ContainerRequestFilter;
import jakarta.ws.rs.core.Response;
import jakarta.ws.rs.ext.Provider;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.ingest.IngestGuard.Decision;

/**
 * Checks the X-Observe-Key of the requests to the OTLP endpoints of the container
 * ({@code /v1/traces}, {@code /v1/logs}) against observed-source.
 */
@Provider
@Priority(Priorities.AUTHENTICATION)
@RequiredArgsConstructor
public class IngestKeyFilter implements ContainerRequestFilter {

  private final IngestGuard guard;
  private final IngestRequestState state;

  @Override
  public void filter(final ContainerRequestContext request) {
    if (!IngestGuard.isIngestPath(request.getUriInfo().getPath())) {
      return;
    }
    Decision decision = guard.check(request.getHeaderString(IngestGuard.KEY_HEADER),
        request.getHeaderString("Origin"));
    if (!decision.accepted()) {
      request.abortWith(Response.status(decision.status()).build());
      return;
    }
    state.setSource(decision.source());
  }
}
